import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { templatesKey, useTemplates, type Template } from './useTemplates';

/** The sheet's claim templates: a form that saves one (a name, an amount the claim form would take, a
 *  note; saving a name again replaces it) and the templates saved. A person's row adds a claim from one. */
function Templates({ sheetId }: { sheetId: string }) {
  const templates = useTemplates(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { name: string; amount: string; note: string }) =>
      postJson<Template>(`/api/sheets/${encodeURIComponent(sheetId)}/templates`, f),
    onSuccess: async () => {
      setName('');
      setAmount('');
      setNote('');
      await queryClient.invalidateQueries({ queryKey: templatesKey(sheetId) });
    },
  });

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  return (
    <section data-testid="templates">
      <form
        data-testid="template-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name, amount, note });
          });
        }}
      >
        <label>
          Template <input data-testid="template-form-name" value={name} onChange={field(setName)} />
        </label>{' '}
        <label>
          Amount <input data-testid="template-form-amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />
        </label>{' '}
        <label>
          Note <input data-testid="template-form-note" value={note} onChange={field(setNote)} />
        </label>{' '}
        <button type="submit" data-testid="template-form-submit" disabled={save.isPending}>
          Save template
        </button>
        {save.isError && <p data-testid="template-form-error">{save.error.message}</p>}
      </form>
      <table data-testid="templates-list">
        <tbody>
          {(templates.data ?? []).map((t) => (
            <tr key={t.name} data-testid={`template-row-${t.name}`}>
              <td data-testid="template-name">{t.name}</td>
              <td data-testid="template-amount">{t.amount}</td>
              <td data-testid="template-note">{t.note}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {templates.isError && <p data-testid="templates-error">{templates.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 6, Component: ({ sheetId }) => <Templates sheetId={sheetId} /> });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim template: its name, amount (two decimals) and note. */
export type Template = { name: string; amount: string; note: string };

export function templatesKey(sheetId: string) {
  return ['sheet', sheetId, 'templates'];
}

/** The sheet's claim templates, by name. */
export function useTemplates(sheetId: string) {
  return useQuery({
    queryKey: templatesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ templates: Template[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/templates`)).templates,
  });
}
import { defineSlot } from '../Slot';

/**
 * The body of the active sheet, rendered once a user is signed in and a sheet is loaded. A
 * feature that shows or changes a sheet's data fills this region. Its data lives under query
 * keys starting ['sheet', sheetId, ...]: loading a sheet drops every such key, so the whole
 * sheet is re-read from the store.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed (URL key `showRetired`): off until turned on, and left as it is
 *  by loading a sheet. */
export function useShowRetired(): [boolean, (on: boolean) => void] {
  const [on, setOn] = useSearchParam('showRetired', asFlag);
  return [on, (v) => setOn(v ? true : undefined)];
}
